import type { Robot } from '../robots';
type Seed = Omit<Robot, 'id' | 'image' | 'seo'> & { couleur: string; objet: string; requete: string; description: string; titre?: string };
const robot = (s: Seed): Robot => {
  const { couleur, objet, requete, description, titre, ...contenu } = s;
  return { ...contenu, id: s.slug, image: { src: `/robots/${s.slug}`, couleur, objet, alt: `Figurine du robot ${s.nom}, en argile mate, avec ${objet.toLocaleLowerCase('fr')} et un anneau vert.` }, seo: { titre: titre ?? `${s.nom} : robot comptable | Memlia`, description, requete } };
};
